-- Ficam com o administrador até serem vinculadas às contas de teste ou transferidas aos lojistas.
do $$
declare
  v_owner uuid; v_vendor uuid; v_order uuid; v record; p record; v_n int;
  v_list jsonb := '[{"slug": "arena", "name": "Arena Suplementos", "city": "Rio Branco, AC", "hex": "#1d4ed8", "verified": true, "about": "Suplementos esportivos das melhores marcas, com atendimento de quem treina.", "hours": "Seg a sáb · 8h às 20h", "address": "Av. Ceará, 1250 · Centro", "segment": "suplementos", "plan": "vitrine", "bps": 700, "fee": 4900}, {"slug": "farmavida", "name": "Farmácia Vida & Saúde", "city": "Tarauacá, AC", "hex": "#be123c", "verified": true, "about": "Farmácia com vitaminas, minerais e cuidados do dia a dia, com orientação farmacêutica.", "hours": "Todos os dias · 7h às 22h", "address": "Rua Coronel Juvêncio, 410 · Centro", "segment": "farmacia", "plan": "destaque", "bps": 500, "fee": 9900}, {"slug": "erva-viva", "name": "Erva Viva Fitoterápicos", "city": "Feijó, AC", "hex": "#166534", "verified": true, "about": "Fitoterápicos e produtos da floresta, de produtores do Acre e da Amazônia.", "hours": "Seg a sex · 8h às 18h", "address": "Rua Plácido de Castro, 88 · Centro", "segment": "naturais", "plan": "basico", "bps": 1000, "fee": 0}, {"slug": "emporio", "name": "Empório Verde Natural", "city": "Feijó, AC", "hex": "#4d7c0f", "verified": false, "about": "Alimentos naturais, proteínas vegetais e opções sem lactose.", "hours": "Seg a sáb · 8h às 19h", "address": "Travessa das Palmeiras, 35 · Bairro da Pista", "segment": "naturais", "plan": "basico", "bps": 1000, "fee": 0}, {"slug": "studio-move", "name": "Studio Move Fitwear", "city": "Rio Branco, AC", "hex": "#be185d", "verified": true, "about": "Moda fitness feminina com tecidos tecnológicos e modelagem que valoriza.", "hours": "Seg a sáb · 9h às 19h", "address": "Shopping Via Verde, loja 214", "segment": "roupas", "plan": "vitrine", "bps": 700, "fee": 4900}, {"slug": "base-athletic", "name": "Base Athletic", "city": "Tarauacá, AC", "hex": "#1e293b", "verified": false, "about": "Roupas masculinas para treino, corrida e o dia a dia ativo.", "hours": "Seg a sáb · 9h às 18h", "address": "Rua Floriano Peixoto, 520 · Centro", "segment": "roupas", "plan": "basico", "bps": 1000, "fee": 0}, {"slug": "casa-do-treino", "name": "Casa do Treino", "city": "Feijó, AC", "hex": "#b45309", "verified": true, "about": "Equipamentos e acessórios para montar o seu espaço de treino.", "hours": "Seg a sáb · 8h às 18h", "address": "Av. Getúlio Vargas, 77 · Centro", "segment": "outros", "plan": "vitrine", "bps": 700, "fee": 4900}]'::jsonb;
  p_list jsonb := '[{"vendor": "arena", "ref": "whey-900", "name": "Whey Protein 900 g", "category": "suplementos", "price": 14990, "old": 17990, "img": "https://nextvita.life/loja/v2/whey.webp", "text": "Proteína de alto valor biológico para recuperação muscular.", "stock": 12, "sku": "ARE-101"}, {"vendor": "arena", "ref": "whey-shaker", "name": "Kit Whey + Coqueteleira", "category": "suplementos", "price": 16990, "old": null, "img": "https://nextvita.life/loja/v2/kit-whey-coqueteleira.webp", "text": "Whey com coqueteleira para levar ao treino.", "stock": 4, "sku": "ARE-102"}, {"vendor": "arena", "ref": "pre-treino", "name": "Pré-treino 300 g", "category": "suplementos", "price": 11990, "old": 13990, "img": "https://nextvita.life/loja/v2/pre-treino.webp", "text": "Energia e foco para treinos intensos.", "stock": 30, "sku": "ARE-103"}, {"vendor": "emporio", "ref": "proteina-vegetal", "name": "Proteína Vegetal 500 g", "category": "nutricao", "price": 12990, "old": null, "img": "https://nextvita.life/loja/v2/proteina-vegetal.webp", "text": "Opção sem lactose para o dia a dia.", "stock": 12, "sku": "EMP-101"}, {"vendor": "erva-viva", "ref": "oleo-copaiba", "name": "Óleo de Copaíba 30 ml", "category": "fitoterapicos", "price": 3990, "old": null, "img": "https://nextvita.life/loja/v2/oleo-copaiba.webp", "text": "Óleo-resina de copaíba envasado em frasco âmbar com conta-gotas.", "stock": 12, "sku": "ERV-101"}, {"vendor": "erva-viva", "ref": "cha-camomila", "name": "Chá de Camomila 30 sachês", "category": "fitoterapicos", "price": 1490, "old": null, "img": "https://nextvita.life/loja/v2/cha-camomila.webp", "text": "Flores de camomila desidratadas em sachês para infusão.", "stock": 4, "sku": "ERV-102"}, {"vendor": "erva-viva", "ref": "guarana-po", "name": "Guaraná em Pó 100 g", "category": "fitoterapicos", "price": 2490, "old": 2990, "img": "https://nextvita.life/loja/v2/guarana-po.webp", "text": "Guaraná da Amazônia moído para sucos e vitaminas.", "stock": 30, "sku": "ERV-103"}, {"vendor": "farmavida", "ref": "multivitaminico", "name": "Multivitamínico 120 cápsulas", "category": "vitaminas", "price": 6990, "old": null, "img": "https://nextvita.life/loja/v2/multivitaminico.webp", "text": "Complexo de vitaminas e minerais para a rotina.", "stock": 12, "sku": "FAR-101"}, {"vendor": "farmavida", "ref": "vitamina-d", "name": "Vitamina D3 60 cápsulas", "category": "vitaminas", "price": 4990, "old": 5990, "img": "https://nextvita.life/loja/v2/vitamina-d.webp", "text": "Apoio à saúde óssea e imunidade.", "stock": 4, "sku": "FAR-102"}, {"vendor": "base-athletic", "ref": "camiseta-regata", "name": "Regata Dry Fit Masculina", "category": "roupas-masculinas", "price": 7990, "old": null, "img": "https://nextvita.life/loja/v2/regata.webp", "text": "Tecido leve que seca rápido, ideal para musculação.", "stock": 12, "sku": "BAS-101"}, {"vendor": "base-athletic", "ref": "conjunto-treino-m", "name": "Conjunto Treino Masculino", "category": "roupas-masculinas", "price": 15990, "old": 18990, "img": "https://nextvita.life/loja/v2/conjunto-masculino.webp", "text": "Camiseta e bermuda de alta mobilidade.", "stock": 4, "sku": "BAS-102"}, {"vendor": "base-athletic", "ref": "camiseta-oversized", "name": "Camiseta Performance", "category": "roupas-masculinas", "price": 8990, "old": null, "img": "https://nextvita.life/loja/v2/camiseta-performance.webp", "text": "Conforto e respirabilidade para todo treino.", "stock": 30, "sku": "BAS-103"}, {"vendor": "studio-move", "ref": "conjunto-fem-1", "name": "Conjunto Top + Legging Preto", "category": "roupas-femininas", "price": 17990, "old": null, "img": "https://nextvita.life/loja/v2/conjunto-preto.webp", "text": "Top com sustentação e legging de cintura alta.", "stock": 12, "sku": "STU-101"}, {"vendor": "studio-move", "ref": "conjunto-fem-2", "name": "Conjunto Rosé Seamless", "category": "roupas-femininas", "price": 18990, "old": 21990, "img": "https://nextvita.life/loja/v2/conjunto-rose.webp", "text": "Modelagem sem costura, toque macio.", "stock": 4, "sku": "STU-102"}, {"vendor": "studio-move", "ref": "conjunto-fem-3", "name": "Conjunto Azul Marinho", "category": "roupas-femininas", "price": 19990, "old": null, "img": "https://nextvita.life/loja/v2/conjunto-marinho.webp", "text": "Conjunto com jaqueta para o antes e depois do treino.", "stock": 30, "sku": "STU-103"}, {"vendor": "studio-move", "ref": "legging", "name": "Legging Compressão", "category": "roupas-femininas", "price": 11990, "old": null, "img": "https://nextvita.life/loja/mulher4.webp", "text": "Compressão confortável e cós alto.", "stock": 8, "sku": "STU-104"}, {"vendor": "casa-do-treino", "ref": "halteres", "name": "Par de Halteres Emborrachados", "category": "acessorios", "price": 12990, "old": null, "img": "https://nextvita.life/loja/v2/halteres.webp", "text": "Peso fixo com revestimento antiderrapante.", "stock": 12, "sku": "CAS-101"}, {"vendor": "casa-do-treino", "ref": "kit-barra", "name": "Kit Anilhas e Barra", "category": "acessorios", "price": 39990, "old": null, "img": "https://nextvita.life/loja/v2/kit-barra.webp", "text": "Para treino de força completo em casa.", "stock": 4, "sku": "CAS-102"}, {"vendor": "casa-do-treino", "ref": "tapete", "name": "Tapete de Treino Antiderrapante", "category": "acessorios", "price": 8990, "old": null, "img": "https://nextvita.life/loja/v2/tapete.webp", "text": "Alta aderência para alongamento e funcional.", "stock": 30, "sku": "CAS-103"}, {"vendor": "casa-do-treino", "ref": "coqueteleira", "name": "Coqueteleira 600 ml", "category": "acessorios", "price": 3990, "old": null, "img": "https://nextvita.life/loja/v2/coqueteleira.webp", "text": "Tampa de segurança e misturador interno.", "stock": 8, "sku": "CAS-104"}]'::jsonb;
begin
  select id into v_owner from auth.users where lower(email) = 'francdenisbr@gmail.com';
  if v_owner is null or exists (select 1 from public.care_store_vendors where is_demo) then return; end if;
  for v in select * from jsonb_to_recordset(v_list) as x(slug text, name text, city text, hex text, verified boolean, about text, hours text, address text, segment text, plan text, bps int, fee int) loop
    insert into public.care_store_vendors(owner_id,name,slug,segment,description,phone,city,address,offers_delivery,offers_pickup,delivery_fee_cents,free_delivery_from_cents,delivery_area,status,plan,monthly_fee_cents,commission_bps,verified,accent_hex,opening_hours,prep_minutes,delivery_minutes,is_demo)
    values (v_owner,v.name,v.slug,v.segment,v.about,'68999990000',v.city,v.address,true,true,800,19900,'Centro e bairros próximos','ativo',v.plan,v.fee,v.bps,v.verified,v.hex,v.hours,30,180,true)
    returning id into v_vendor;
    insert into public.care_store_products(vendor_id,name,category,description,price_cents,old_price_cents,image_url,stock,min_stock,cost_cents,sku,ref)
    select v_vendor, x.name, x.category, x.text, x.price, x.old, x.img, x.stock, 5, (x.price * 0.55)::int, x.sku, x.ref
      from jsonb_to_recordset(p_list) as x(vendor text, ref text, name text, category text, price int, old int, img text, text text, stock int, sku text)
     where x.vendor = v.slug;
    v_n := 0;
    for p in select * from public.care_store_products where vendor_id = v_vendor order by sku limit 4 loop
      v_n := v_n + 1;
      insert into public.care_store_orders(user_id,customer_name,customer_email,customer_phone,address,items,total_cents,payment_method,status,vendor_id,fulfillment,delivery_fee_cents,commission_cents,vendor_net_cents,created_at)
      values (v_owner, (array['Ana Souza','Carlos Lima','Juliana Rocha','Pedro Alves'])[v_n], 'cliente.teste@nextvita.life', '68999991111',
        case when v_n % 2 = 0 then 'Rua das Flores, 120 · Centro' end,
        jsonb_build_array(jsonb_build_object('id', p.id, 'name', p.name, 'qty', 1, 'price_cents', p.price_cents, 'image_url', p.image_url)),
        p.price_cents + case when v_n % 2 = 0 then 800 else 0 end, (array['pix','cartao','pix','boleto'])[v_n], 'aguardando_pagamento', v_vendor,
        case when v_n % 2 = 0 then 'entrega' else 'retirada' end, case when v_n % 2 = 0 then 800 else 0 end,
        round(p.price_cents * v.bps / 10000.0)::int, p.price_cents + case when v_n % 2 = 0 then 800 else 0 end - round(p.price_cents * v.bps / 10000.0)::int,
        now() - make_interval(hours => v_n * 5))
      returning id into v_order;
      if v_n >= 2 then update public.care_store_orders set status = 'pago' where id = v_order; end if;
      if v_n >= 3 then update public.care_store_orders set status = 'separando' where id = v_order; end if;
      if v_n = 4 then
        update public.care_store_orders set status = 'enviado' where id = v_order;
        update public.care_store_orders set status = 'entregue' where id = v_order;
      end if;
    end loop;
    insert into public.care_store_messages(vendor_id,customer_id,customer_name,from_vendor,body,created_at) values
      (v_vendor, v_owner, 'Ana Souza', false, 'Olá! Vocês têm esse produto para retirar hoje?', now() - interval '40 minutes'),
      (v_vendor, v_owner, 'Ana Souza', true, 'Olá, Ana! Temos sim. Faça o pedido com retirada e mostre o código no balcão.', now() - interval '35 minutes'),
      (v_vendor, v_owner, 'Ana Souza', false, 'Perfeito, obrigada! Vou pedir agora.', now() - interval '30 minutes');
    insert into public.care_store_cash_entries(vendor_id,kind,amount_cents,category,description)
    values (v_vendor,'saida',3500,'embalagem','Sacolas e etiquetas');
  end loop;
end $$;
